-- gallery.velle — cross-base unions exercised end-to-end (Reference §9 extended
-- across unrelated shapes; OQ29): a static union as a field's target type (the
-- polymorphic association), the inverse it infers onto every operand, a derived
-- body on the union, a refinement and a rule over the union, per-operand
-- narrowing in a value expression and in a predicate, and the boundary's
-- type-level refusal of a reference outside the union. And beside the union,
-- a field two shapes share from one declaration (Reference §9, "Sharing a
-- field across shapes"): a post and a photo are each a contribution, and
-- `author` is declared once on the contribution.

act Member {
    name: text
}

-- Every post and every photo has an author. Declared once, on a shape the two
-- take with `is`: `author` is then one declaration on both, readable wherever
-- the two are read as one, and `Member.contributions` is the one inverse it
-- infers, holding posts and photos alike. A contribution has no records of its
-- own: every record of it is a post or a photo.
shape Contribution {
    author: one Member
    -- A contribution may come from an outside source, with a line saying how. A
    -- line without the source is refused at the door by one prohibition over
    -- Content (below), and the compiler reads that promise wherever the line is
    -- tested, so `credit` reads `source.name` with a plain dot (Reference §21).
    source: one Source?
    creditLine: text?
    credit: text = if creditLine is some then source.name else ""
}

-- a wire service or a studio a contribution may be credited to
act Source {
    name: text
}

act Post is Contribution {
    body: text
}

act Photo is Contribution {
    caption: text
}

-- Content is a static union: a pure `or` of base shapes, so it is a stable
-- field type. It exposes only what both operands inherit from ONE declaration —
-- `id`, the `comments` inverse inferred through Comment.target below, and
-- `author`, which both take from Contribution. A field the two declared
-- separately would reach the union's readers only by narrowing (below).
shape Content = Post or Photo {
    commentCount: integer = count(comments)     -- a derived body over the shared inverse
}

-- the polymorphic association: one role, filled by an instance of either shape
act Comment {
    target: one Content
    author: one Member
    body: text
}
-- inferred inverse: Post.comments, Photo.comments, and Content.comments, from Comment.target

-- A credit line names its source. One prohibition over the union is enforced
-- on every post and every photo, and is the fact `credit` reads from.
never (Content where creditLine is some and source is none)

-- Nobody comments on their own post. Narrowing in a conjunction: `target is Post`
-- licenses `target.author` in what follows it.
never (Comment where target is Post and target.author == author)

-- a refinement over the union, and a rule reacting to entry into it
shape Popular = Content where count(comments) >= 2

shape PopularityNotice {
    content: one Content
    noticedOn: DateTime
}

rule NotePopularity when Popular {
    PopularityNotice from { content: this, noticedOn: now }
}

-- Narrowing in a value expression: each branch reads its operand's own field.
-- `author` is one declaration both operands take, so it is read directly.
shape CommentNotice {
    recipient: one Member
    comment: one Comment
    excerpt: text
}

rule NotifyAuthor when Comment {
    CommentNotice from {
        recipient: target.author
        comment: this
        excerpt: if target is Post then target.body else target.caption
